package cn.iocoder.yudao.module.zsjos.dal.mysql.positioning; import cn.iocoder.yudao.framework.mybatis.core.mapper.BaseMapperX; import cn.iocoder.yudao.module.zsjos.dal.dataobject.positioning.InterviewRecordDO; import org.apache.ibatis.annotations.Mapper; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import java.util.List; @Mapper public interface InterviewRecordMapper extends BaseMapperX<InterviewRecordDO>{default List<InterviewRecordDO> selectByAccount(Long id){return selectList(new LambdaQueryWrapper<InterviewRecordDO>().eq(InterviewRecordDO::getAccountId,id).orderByDesc(InterviewRecordDO::getId));}default int confirm(Long id,Integer version){return update(null,new com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<InterviewRecordDO>().eq(InterviewRecordDO::getId,id).eq(InterviewRecordDO::getVersion,version).eq(InterviewRecordDO::getConfirmed,false).set(InterviewRecordDO::getConfirmed,true).set(InterviewRecordDO::getStatus,"confirmed").set(InterviewRecordDO::getVersion,version+1));}}
